import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:easy_localization/easy_localization.dart';
import 'package:excel/excel.dart' as xls;
import 'package:flutter/material.dart';
import 'package:flutter/services.dart' show rootBundle;
import 'package:path_provider/path_provider.dart';
import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:share_plus/share_plus.dart';

enum TableExportFormat { csv, excel, pdf }

/// Shown on every exported file as a lightweight "generated by" mark —
/// PDF gets the actual logo image alongside it; CSV/Excel (no image
/// support) get this name as plain text instead.
const brandName = 'eSIM Dafter';

/// Generic "export a table of strings" helper shared by every page with
/// export buttons (Numbers, Reports, Shipments & Operations). Builds the
/// file in memory, writes it to the app's own temp dir, then hands it to
/// the OS share sheet (`share_plus`) so the seller can save/send it
/// without needing Android's scoped-storage write permissions.
///
/// Callers pass already-`.tr()`-resolved [headers]/[rows]/[title] so the
/// exported file matches whichever language the app is currently
/// showing. The PDF additionally sets right-to-left layout for Arabic
/// and reuses the app's own bundled `IBMPlexSansArabic` font — the `pdf`
/// package's default font has no Arabic glyphs at all.
Future<void> exportTable({
  required BuildContext context,
  required String title,
  required List<String> headers,
  required List<List<String>> rows,
  required TableExportFormat format,
  required String fileNamePrefix,
}) async {
  final isArabic = context.locale.languageCode == 'ar';

  final Uint8List bytes;
  final String extension;
  switch (format) {
    case TableExportFormat.csv:
      bytes = _buildCsv(title, headers, rows);
      extension = 'csv';
    case TableExportFormat.excel:
      bytes = _buildExcel(title, headers, rows);
      extension = 'xlsx';
    case TableExportFormat.pdf:
      bytes = await _buildPdf(title, headers, rows, isArabic: isArabic);
      extension = 'pdf';
  }

  final timestamp = DateTime.now().toIso8601String().replaceAll(RegExp(r'[:.]'), '-');
  final fileName = '${fileNamePrefix}_$timestamp.$extension';
  final dir = await getTemporaryDirectory();
  final file = File('${dir.path}/$fileName');
  await file.writeAsBytes(bytes);
  await Share.shareXFiles([XFile(file.path)], subject: fileName);
}

/// A leading UTF-8 BOM makes Excel (unlike most other CSV readers)
/// detect the encoding correctly and render Arabic text properly
/// instead of garbling it — without it, a CSV with Arabic content opens
/// as mojibake in Excel specifically, even though the bytes themselves
/// are valid UTF-8. The app-name line up top is the closest CSV (a
/// plain-text format) can get to the "app name + logo" branding the
/// PDF/Excel exports carry — there's no logo to embed in a text file.
Uint8List _buildCsv(String title, List<String> headers, List<List<String>> rows) {
  String escape(String field) {
    if (field.contains(',') || field.contains('"') || field.contains('\n')) {
      return '"${field.replaceAll('"', '""')}"';
    }
    return field;
  }

  final buffer = StringBuffer();
  buffer.writeln(escape('$brandName — $title'));
  buffer.writeln();
  buffer.writeln(headers.map(escape).join(','));
  for (final row in rows) {
    buffer.writeln(row.map(escape).join(','));
  }

  const bom = [0xEF, 0xBB, 0xBF];
  return Uint8List.fromList([...bom, ...utf8.encode(buffer.toString())]);
}

/// Excel worksheets have no simple text/image mix API in the `excel`
/// package (no drawing/image insertion support at all as of this
/// writing) — so branding here is text-only: a bold app-name + title
/// row above the real header row, same idea as the CSV.
Uint8List _buildExcel(String title, List<String> headers, List<List<String>> rows) {
  final workbook = xls.Excel.createExcel();
  final sheetName = workbook.getDefaultSheet()!;
  final sheet = workbook[sheetName];

  sheet.appendRow([xls.TextCellValue('$brandName — $title')]);
  sheet.cell(xls.CellIndex.indexByColumnRow(columnIndex: 0, rowIndex: 0)).cellStyle = xls.CellStyle(bold: true, fontSize: 14);
  sheet.appendRow(const []);
  sheet.appendRow(headers.map((h) => xls.TextCellValue(h)).toList());
  for (final row in rows) {
    sheet.appendRow(row.map((cell) => xls.TextCellValue(cell)).toList());
  }

  final bytes = workbook.save();
  return Uint8List.fromList(bytes ?? const []);
}

Future<Uint8List> _buildPdf(String title, List<String> headers, List<List<String>> rows, {required bool isArabic}) async {
  final regularBytes = await rootBundle.load('assets/fonts/IBMPlexSansArabic-Regular.ttf');
  final boldBytes = await rootBundle.load('assets/fonts/IBMPlexSansArabic-Bold.ttf');
  final regularFont = pw.Font.ttf(regularBytes);
  final boldFont = pw.Font.ttf(boldBytes);
  final logoBytes = await rootBundle.load('assets/icons/icon.png');
  final logoImage = pw.MemoryImage(logoBytes.buffer.asUint8List());

  final doc = pw.Document(theme: pw.ThemeData.withFont(base: regularFont, bold: boldFont));
  final direction = isArabic ? pw.TextDirection.rtl : pw.TextDirection.ltr;

  doc.addPage(
    pw.MultiPage(
      pageFormat: PdfPageFormat.a4,
      textDirection: direction,
      header: (context) => pw.Padding(
        padding: const pw.EdgeInsets.only(bottom: 12),
        child: pw.Row(
          children: [
            pw.ClipRRect(
              horizontalRadius: 6,
              verticalRadius: 6,
              child: pw.Image(logoImage, width: 28, height: 28, fit: pw.BoxFit.cover),
            ),
            pw.SizedBox(width: 8),
            pw.Text(brandName, style: pw.TextStyle(font: boldFont, fontSize: 14)),
            pw.SizedBox(width: 8),
            pw.Text('—', style: pw.TextStyle(font: regularFont, fontSize: 14, color: PdfColors.grey600)),
            pw.SizedBox(width: 8),
            pw.Text(title, style: pw.TextStyle(font: boldFont, fontSize: 14)),
          ],
        ),
      ),
      footer: (context) => pw.Padding(
        padding: const pw.EdgeInsets.only(top: 8),
        child: pw.Center(
          child: pw.Text(
            '$brandName — ${context.pageNumber}/${context.pagesCount}',
            style: pw.TextStyle(font: regularFont, fontSize: 8, color: PdfColors.grey500),
          ),
        ),
      ),
      build: (context) => [
        pw.TableHelper.fromTextArray(
          headers: headers,
          data: rows,
          headerStyle: pw.TextStyle(font: boldFont, fontSize: 10),
          cellStyle: pw.TextStyle(font: regularFont, fontSize: 9),
          headerAlignment: isArabic ? pw.Alignment.centerRight : pw.Alignment.centerLeft,
          cellAlignment: isArabic ? pw.Alignment.centerRight : pw.Alignment.centerLeft,
          cellHeight: 24,
          border: pw.TableBorder.all(color: PdfColors.grey400, width: 0.5),
        ),
      ],
    ),
  );

  return doc.save();
}
